mapper.select:
select job_id, job_name, job_group, invoke_target, cron_expression, misfire_policy, concurrent, status, create_by, create_time, remark 
from sys_job


		AND job_name like concat('%', #{jobName}, '%')


		AND job_group = #{jobGroup}


		AND status = #{status}


		AND invoke_target like concat('%', #{invokeTarget}, '%')

select j.job_id, j.job_name, j.job_group, j.invoke_target, j.cron_expression, j.misfire_policy, j.concurrent, j.status, j.create_by, j.create_time, j.remark, (select coalesce(l.start_time, l.create_time) from sys_job_log l where l.job_name = j.job_name and l.job_group = j.job_group order by l.create_time desc, l.job_log_id desc limit 1) as last_run_time, (select l.status from sys_job_log l where l.job_name = j.job_name and l.job_group = j.job_group order by l.create_time desc, l.job_log_id desc limit 1) as last_run_status from sys_job j
AND j.job_name like concat('%', #{arg1.jobName}, '%')
AND j.job_group = #{arg1.jobGroup}
AND j.status = #{arg1.status}
AND j.invoke_target like concat('%', #{arg1.invokeTarget}, '%')
order by j.job_id

select job_id, job_name, job_group, invoke_target, cron_expression, misfire_policy, concurrent, status, create_by, create_time, remark
from sys_job
where job_id = #{jobId}

mapper.update:
update sys_job
job_name = #{jobName}, job_group = #{jobGroup}, invoke_target = #{invokeTarget}, cron_expression = #{cronExpression}, misfire_policy = #{misfirePolicy}, concurrent = #{concurrent}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where job_id = #{jobId}
